const SYSTEM_PROMPT = "Du är en finansiell nyhetsanalytiker specialiserad på att identifiera potentiella investeringsmöjligheter (köp/sälj-signaler) genom att läsa nyhetsartiklar. Du arbetar åt en privat investerare som vill ha snabb, ärlig och konkret bedömning — inte allmänt hausse-prat.\n\nBRANSCHER ATT BEVAKA (klassificera varje relevant artikel till en av dessa):\n1. AI/tech\n2. Banker\n3. Energi/olja\n4. Guld/råvaror (inkl. litium, koppar, uran, silver)\n5. Försvar\n6. Quantum (spekulativ kategori — flagga alltid som högre risk)\n\nOm en artikel inte rör någon av dessa branscher eller inte innehåller någon agerbar signal ska den ignoreras helt (returnera ingen post för den).\n\nDIN UPPGIFT för varje relevant artikel:\n1. Identifiera vilket bolag/bransch artikeln rör\n2. Bedöm om det är en köpsignal, säljsignal, eller enbart bevakningsvärd (ingen tydlig riktning ännu)\n3. Sätt en konfidensgrad: Hög / Medel / Låg\n   - Hög: konkret, mätbar händelse med tydlig historisk koppling till kursrörelse (t.ex. förvärv, resultatöverraskning, stort kontrakt, regulatoriskt godkännande)\n   - Medel: relevant händelse men med osäker eller indirekt påverkan\n   - Låg: spekulativt, rykte, eller svag koppling till faktisk kurspåverkan\n4. Skriv en kort motivering (max 2 meningar) — vad hände och varför det spelar roll\n5. Ange källa (URL till originalartikeln)\n\nVIKTIGA PRINCIPER:\n- Var ärligt återhållsam. De flesta nyheter är brus — det är okej att en dag inte ha några Hög-konfidens flaggor.\n- Skilj tydligt på faktisk händelse (t.ex. \"bolag X rapporterade 15% vinstökning\") och spekulation (t.ex. \"analytiker tror att...\").\n- Om samma bolag nämns i flera artiklar samma dag, slå ihop till en post med den starkaste signalen.\n- Hitta aldrig på siffror, bolagsnamn eller händelser som inte finns i texten.\n- Om osäker på om något är en verklig signal — sätt lägre konfidensgrad snarare än att gissa högt.\n\nOUTPUT-FORMAT — svara ENDAST med giltig JSON, ingen text utanför, i detta schema:\n{\n  \"flaggor\": [\n    {\n      \"bolag\": \"string\",\n      \"bransch\": \"AI/tech | Banker | Energi/olja | Guld/råvaror | Försvar | Quantum\",\n      \"signal\": \"Köp | Sälj | Bevaka\",\n      \"konfidensgrad\": \"Hög | Medel | Låg\",\n      \"motivering\": \"string (max 2 meningar)\",\n      \"källa\": \"url\"\n    }\n  ]\n}\n\nOm inga relevanta flaggor hittas i artikeln/artiklarna: returnera {\"flaggor\": []}";

const items = $input.all();
const datum = new Date().toISOString().slice(0, 10);

if (items.length === 0) {
  return [{
    json: {
      systemPrompt: SYSTEM_PROMPT,
      userMessage: 'Inga artiklar hittades i denna körning.',
      runLabel: 'Okänd körning',
      runKey: 'SE',
      datum,
      articleCount: 0
    }
  }];
}

const runLabel = items[0].json.runLabel;
const runKey = items[0].json.runKey;

// Fair round-robin sampling across sources instead of a flat slice, so a
// high-volume source (e.g. 100+ articles) can't crowd out smaller ones
// (e.g. 4 articles) before the cap is reached.
const MAX_PER_SOURCE = 8;
const MAX_ARTICLES = 60;

const bySource = {};
const sourceOrder = [];
for (const item of items) {
  const src = item.json.source || 'Okänd källa';
  if (!bySource[src]) {
    bySource[src] = [];
    sourceOrder.push(src);
  }
  bySource[src].push(item);
}

const selected = [];
for (let round = 0; round < MAX_PER_SOURCE && selected.length < MAX_ARTICLES; round++) {
  for (const src of sourceOrder) {
    if (selected.length >= MAX_ARTICLES) break;
    const bucket = bySource[src];
    if (bucket[round]) selected.push(bucket[round]);
  }
}

const articles = selected.map((item, i) => {
  const j = item.json;
  return `${i + 1}. Källa: ${j.source || 'Okänd källa'}\nTitel: ${j.title}\nIngress: ${j.ingress || '(ingen ingress tillgänglig)'}\nLänk: ${j.link}`;
}).join('\n\n');

const userMessage = `Körning: ${runLabel}\nDatum: ${datum}\nAntal artiklar hämtade totalt: ${items.length} (från ${sourceOrder.length} källor)\nAntal artiklar i denna batch (rättvist urval, max ${MAX_PER_SOURCE} per källa): ${selected.length}\n\nAnalysera artiklarna nedan enligt instruktionerna i systempromptet och returnera ENDAST giltig JSON enligt schemat — ingen text utanför JSON-objektet.\n\n${articles}`;

return [{
  json: {
    systemPrompt: SYSTEM_PROMPT,
    userMessage,
    runLabel,
    runKey,
    datum,
    articleCount: selected.length,
    totalFetched: items.length
  }
}];

const response = $input.first().json;
const upstream = $('Build Article Batch').first().json;

let flaggor = [];
try {
  const textBlock = (response.content || []).find(c => c.type === 'text');
  const raw = textBlock ? textBlock.text : '{}';
  const parsed = JSON.parse(raw);
  flaggor = Array.isArray(parsed.flaggor) ? parsed.flaggor : [];
} catch (e) {
  flaggor = [];
}

return [{
  json: {
    flaggor,
    datum: upstream.datum,
    körning: upstream.runLabel,
    runKey: upstream.runKey,
    articleCount: upstream.articleCount,
    flagCount: flaggor.length
  }
}];

const data = $input.first().json;
const flaggor = data.flaggor || [];
const datum = data.datum;
const körning = data.körning;
const articleCount = data.articleCount || 0;

const confOrder = { 'Hög': 0, 'Medel': 1, 'Låg': 2 };
const köp = flaggor.filter(f => f.signal === 'Köp').sort((a, b) => (confOrder[a.konfidensgrad] ?? 3) - (confOrder[b.konfidensgrad] ?? 3));
const bevaka = flaggor.filter(f => f.signal === 'Bevaka');
const sälj = flaggor.filter(f => f.signal === 'Sälj');
const topp = flaggor.find(f => f.konfidensgrad === 'Hög') || null;
const confEmoji = { 'Hög': '🟢', 'Medel': '🟡', 'Låg': '🔴' };

let html = `<h2>📊 DAGLIG MARKNADSBRIEF — ${datum} — ${körning}</h2>`;

if (topp) {
  html += `<p><strong>🟢 TOPP-FLAGGA</strong><br>${topp.bolag} — ${topp.bransch} — Konfidensgrad: Hög<br>${topp.motivering}<br>→ Signal: ${topp.signal} | Källa: <a href="${topp.källa}">${topp.källa}</a></p><hr>`;
}

html += '<p><strong>📈 MÖJLIGHETER (rankade efter konfidensgrad)</strong></p><ol>';
if (köp.length === 0) {
  html += '<li>Inga köpsignaler idag.</li>';
} else {
  köp.forEach(f => {
    html += `<li>${f.bolag} — ${f.bransch} — ${confEmoji[f.konfidensgrad] || ''} ${f.konfidensgrad}<br>Vad: ${f.motivering}<br>Källa: <a href="${f.källa}">${f.källa}</a></li>`;
  });
}
html += '</ol><hr>';

html += '<p><strong>⚠️ BEVAKA (svagare signaler)</strong></p><ul>';
if (bevaka.length === 0) {
  html += '<li>Inga bevakningsposter idag.</li>';
} else {
  bevaka.forEach(f => { html += `<li>${f.bolag}: ${f.motivering}</li>`; });
}
html += '</ul><hr>';

html += '<p><strong>🔴 RISKFLAGGOR (negativa nyheter)</strong></p><ul>';
if (sälj.length === 0) {
  html += '<li>Inga riskflaggor idag.</li>';
} else {
  sälj.forEach(f => { html += `<li>${f.bolag}: ${f.motivering}</li>`; });
}
html += '</ul><hr>';

html += `<p>📉 Sammanfattning: ${articleCount} artiklar skannade, ${flaggor.length} flaggor genererade.</p>`;

const subject = `📊 Marknadsbrief — ${datum} — ${körning}`;

return [{ json: { subject, htmlBody: html } }];
